mapper.select:
SELECT g.goods_id AS goodsId, g.user_id AS userId, g.goods_desc AS goodsDesc, g.price, g.original_price AS originalPrice, g.tags, g.create_time AS createTime FROM favourite f INNER JOIN goods g ON f.item_id = g.goods_id
f.user_id = #{currentUserId}
AND g.create_time >= #{param.beginTime}
AND g.create_time < DATE_ADD(#{param.endTime}, INTERVAL 1 DAY)
ORDER BY ${param.sortRules}
ORDER BY f.create_time DESC

WITH RECURSIVE CommentPath AS ( SELECT id, goods_id, parent_id, text, picture, son, user_id, reply_user_id, create_time, good_or_bad, 0 AS level FROM comment_goods WHERE id = #{commentId}
UNION ALL
SELECT c.id, c.goods_id, c.parent_id, c.text, c.picture, c.son, c.user_id, c.reply_user_id, c.create_time, c.good_or_bad, cp.level + 1 AS level FROM comment_goods c INNER JOIN CommentPath cp ON c.id = cp.parent_id) SELECT cp.id AS id, cp.goods_id AS goods_id, cp.parent_id AS parent_id, cp.text AS text, cp.picture AS picture, cp.son AS son, cp.create_time AS create_time, cp.level AS level, cp.user_id AS user_id, U1.avatar AS user_avatar, U1.user_name AS user_name, cp.reply_user_id AS reply_user_id, U2.avatar AS reply_user_avatar, U2.user_name AS reply_user_name FROM CommentPath cp LEFT JOIN user U1 ON U1.user_id = cp.user_id LEFT JOIN user U2 ON U2.user_id = cp.reply_user_id ORDER BY cp.level DESC
